func (o *AllocationRule) LoadAllocationRuleWeights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AllocationRuleWeights = nil
	o.R.Loaded.AllocationRuleWeights = false

	related, err := o.AllocationRuleWeights(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.AllocationRule = o
		rel.R.Loaded.AllocationRule = true
	}

	o.R.AllocationRuleWeights = related
	o.R.Loaded.AllocationRuleWeights = true
	return nil
}

// LoadAllocationRuleWeights loads the allocationRule's AllocationRuleWeights into the .R struct
func (os AllocationRuleSlice) LoadAllocationRuleWeights(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	allocationRuleWeights, err := os.AllocationRuleWeights(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AllocationRuleWeights = nil
		o.R.Loaded.AllocationRuleWeights = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range allocationRuleWeights {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.ID == rel.RuleID) {
				continue
			}

			rel.R.AllocationRule = o
			rel.R.Loaded.AllocationRule = true

			o.R.AllocationRuleWeights = append(o.R.AllocationRuleWeights, rel)
		}
	}

	return nil
}

