// allocationRuleC is where relationship counts are stored.
type allocationRuleC struct {
	AllocationRuleWeights *int64
	ItemAllocations       *int64
}

// PreloadCount sets a count in the C struct by name
func (o *AllocationRule) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AllocationRuleWeights":
		o.C.AllocationRuleWeights = &count
	case "ItemAllocations":
		o.C.ItemAllocations = &count
	}
	return nil
}

type allocationRuleCountPreloader struct {
	AllocationRuleWeights func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	ItemAllocations       func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildAllocationRuleCountPreloader() allocationRuleCountPreloader {
	return allocationRuleCountPreloader{
		AllocationRuleWeights: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*AllocationRule]("AllocationRuleWeights", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = AllocationRules.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(AllocationRuleWeights.NameAsExpr()),
					sm.Where(psql.Quote(AllocationRuleWeights.Alias(), "household_id").EQ(psql.Quote(parent, "household_id"))),
					sm.Where(psql.Quote(AllocationRuleWeights.Alias(), "rule_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		ItemAllocations: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*AllocationRule]("ItemAllocations", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = AllocationRules.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(ItemAllocations.NameAsExpr()),
					sm.Where(psql.Quote(ItemAllocations.Alias(), "household_id").EQ(psql.Quote(parent, "household_id"))),
					sm.Where(psql.Quote(ItemAllocations.Alias(), "rule_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

type allocationRuleCountThenLoader[Q orm.Loadable] struct {
	AllocationRuleWeights func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ItemAllocations       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildAllocationRuleCountThenLoader[Q orm.Loadable]() allocationRuleCountThenLoader[Q] {
	type AllocationRuleWeightsCountInterface interface {
		LoadCountAllocationRuleWeights(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ItemAllocationsCountInterface interface {
		LoadCountItemAllocations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return allocationRuleCountThenLoader[Q]{
		AllocationRuleWeights: countThenLoadBuilder[Q](
			"AllocationRuleWeights",
			func(ctx context.Context, exec bob.Executor, retrieved AllocationRuleWeightsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAllocationRuleWeights(ctx, exec, mods...)
			},
		),
		ItemAllocations: countThenLoadBuilder[Q](
			"ItemAllocations",
			func(ctx context.Context, exec bob.Executor, retrieved ItemAllocationsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountItemAllocations(ctx, exec, mods...)
			},
		),
	}
}

