type allocationRuleJoins[Q dialect.Joinable] struct {
	typ                   string
	AllocationRuleWeights modAs[Q, allocationRuleWeightColumns]
	Category              modAs[Q, categoryColumns]
	Household             modAs[Q, householdColumns]
	ProductConcept        modAs[Q, productConceptColumns]
	ProductVariant        modAs[Q, productVariantColumns]
	ItemAllocations       modAs[Q, itemAllocationColumns]
}

func (j allocationRuleJoins[Q]) aliasedAs(alias string) allocationRuleJoins[Q] {
	return buildAllocationRuleJoins[Q](buildAllocationRuleColumns(alias), j.typ)
}

func buildAllocationRuleJoins[Q dialect.Joinable](cols allocationRuleColumns, typ string) allocationRuleJoins[Q] {
	return allocationRuleJoins[Q]{
		typ: typ,
		AllocationRuleWeights: modAs[Q, allocationRuleWeightColumns]{
			c: AllocationRuleWeights.Columns,
			f: func(to allocationRuleWeightColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AllocationRuleWeights.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.RuleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Category: modAs[Q, categoryColumns]{
			c: Categories.Columns,
			f: func(to categoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Categories.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.CategoryID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		ProductConcept: modAs[Q, productConceptColumns]{
			c: ProductConcepts.Columns,
			f: func(to productConceptColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ProductConcepts.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.ProductConceptID),
					))
				}

				return mods
			},
		},
		ProductVariant: modAs[Q, productVariantColumns]{
			c: ProductVariants.Columns,
			f: func(to productVariantColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ProductVariants.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.ProductVariantID),
					))
				}

				return mods
			},
		},
		ItemAllocations: modAs[Q, itemAllocationColumns]{
			c: ItemAllocations.Columns,
			f: func(to itemAllocationColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, ItemAllocations.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.RuleID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
